INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (58, 1, 'Kafka 와 RabbitMQ 의 설계 차이 알기', 'Kafka 는 메시지를 읽어도 **사라지지 않아서** 과거 데이터를 다시 읽을 수 있습니다. RabbitMQ 와 비교한 설계 철학으로 알맞은 것은 무엇일까요?', '한쪽은 "전달"이 목적이고, 한쪽은 "보존"이 목적입니다.', NULL, NULL, '[]', 'choice', '["RabbitMQ 는 \\"전달\\"이 목적이라 consumer 가 받아 ack 하면 큐에서 삭제되고, Kafka 는 \\"보존\\"이 목적이라 로그로 쌓아 두고 consumer 가 자기 offset 으로 읽어 간다", "둘 다 읽으면 바로 삭제된다", "Kafka 는 브로커가 consumer 마다 어디까지 읽었는지 직접 추적해 삭제한다", "RabbitMQ 만 디스크에 저장한다"]', 0, 'Kafka 는 메시지를 보존 기간(retention) 동안 디스크 로그에 남기고, consumer 가 **자기 offset** 을 들고 와서 읽습니다. 그래서 버그를 고친 뒤 offset 을 되감아 **재처리**할 수 있고, 여러 consumer 가 서로 독립적으로 읽을 수 있습니다. RabbitMQ 는 소비하면 큐에서 사라집니다.', NULL, NULL, NULL, NULL),
  (58, 2, '토픽과 파티션의 관계 알기', 'Kafka 에서 **토픽**과 **파티션**의 관계로 알맞은 것은 무엇일까요?', '토픽은 논리적 이름이고, 실제로 디스크에 쌓이는 단위는 따로 있습니다.', NULL, NULL, '[]', 'choice', '["토픽 하나는 항상 파티션 하나로만 이루어진다", "토픽은 메시지를 분류하는 논리적 단위이고, 파티션이 실제 저장 단위(append-only 로그)이다. 토픽 하나는 하나 이상의 파티션으로 이루어진다", "파티션은 토픽 이름이 같은 메시지를 모은 논리적 분류이다", "파티션은 consumer 를 가리키는 말이다"]', 1, '토픽(`orders`, `payments` 같은 이름)은 논리적 개념이고 **파티션**이 물리적 저장 단위입니다. 파티션은 메시지가 순서대로 쌓이는 append-only 로그이고, 브로커에 분산되어 저장됩니다. 파티션을 늘리면 수평 확장과 병렬 처리가 가능해집니다.', NULL, NULL, NULL, NULL),
  (58, 3, 'offset 이 유일한 범위 알기', 'partition-0 의 offset 3 메시지와 partition-1 의 offset 3 메시지는 어떤 관계일까요?', 'offset 은 어디서 유일할까요?', NULL, NULL, '[]', 'choice', '["같은 메시지이다. offset 은 토픽 전체에서 유일하다", "같은 메시지가 복제된 것이다", "서로 다른 메시지이다. offset 은 **파티션 안에서만** 유일하다", "둘 중 하나는 삭제된 것이다"]', 2, 'offset 은 **파티션 안에서의 순번**입니다. 그래서 메시지를 정확히 지목하려면 (토픽, 파티션, offset) 세 가지가 필요합니다. 순서 보장도 **파티션 안에서만** 됩니다. 같은 키를 가진 메시지가 항상 같은 파티션으로 가게 하는 이유가 여기에 있습니다.', NULL, NULL, NULL, NULL),
  (58, 4, 'Consumer Group 의 파티션 배정 알기', '파티션이 3개인 토픽을 같은 group.id 의 컨슈머 **5개**가 읽으면 어떻게 될까요?', '파티션 하나는 같은 그룹 안에서 동시에 한 컨슈머만 읽습니다.', NULL, NULL, '[]', 'choice', '["5개가 파티션 3개를 균등하게 나눠 읽는다", "컨슈머 5개 모두 모든 파티션을 읽어 메시지가 5번 처리된다", "파티션이 자동으로 5개로 늘어난다", "컨슈머 3개가 파티션을 하나씩 맡고, **나머지 2개는 놀게** 된다"]', 3, '같은 그룹 안에서 파티션은 **동시에 하나의 컨슈머만** 읽습니다. 컨슈머가 파티션보다 많으면 남는 컨슈머는 놉니다. 그래서 병렬도의 상한은 **파티션 수**입니다. 반대로 파티션이 더 많으면 한 컨슈머가 여러 파티션을 맡습니다. 다른 그룹(group.id)은 독립적으로 전체를 읽습니다.', NULL, NULL, NULL, NULL),
  (58, 5, 'Leader/Follower 구조가 필요한 이유 알기', 'Kafka 는 파티션 복사본 중 **하나(Leader)만 쓰기를 받고**, 나머지(Follower)는 따라가기만 합니다. 이렇게 하는 이유는 무엇일까요?', '복사본이 모두 쓰기를 받으면 같은 파티션의 기록 순서가 복사본마다 달라질 수 있습니다.', NULL, NULL, '[]', 'choice', '["복사본마다 기록 순서가 어긋나지 않게 해서 **파티션 안의 순서 보장**을 지키기 위해서이다", "Follower 가 많을수록 쓰기가 빨라지기 때문이다", "Follower 는 읽기 전용 캐시라서 필요하다", "라이선스 비용을 줄이기 위해서이다"]', 0, '모든 복사본이 동시에 쓰기를 받으면 두 producer 의 메시지 순서가 브로커마다 달리 기록될 수 있어 **파티션 안의 순서 보장**이 깨집니다. 그래서 쓰기는 Leader 한 곳으로 모으고, Follower 는 Leader 의 로그를 그대로 복제합니다. Leader 가 죽으면 Follower 중 하나가 새 Leader 가 됩니다.', NULL, NULL, NULL, NULL),
  (58, 6, 'replication factor 알기', 'replication factor 가 **3** 이면 파티션 하나가 어떻게 저장될까요?', '복제 수는 "총 몇 개의 복사본"을 뜻합니다.', NULL, NULL, '[]', 'choice', '["파티션이 3조각으로 쪼개져 저장된다", "파티션 하나가 서로 다른 브로커 3개에 저장된다 (Leader 1개 + Follower 2개)", "토픽이 3개로 늘어난다", "브로커 3대 중 1대에만 저장되고 2대는 비워 둔다"]', 1, 'replication factor 는 파티션의 **복사본 수**입니다. 3 이면 서로 다른 브로커 3대에 복사본이 있고, 하나는 Leader, 둘은 Follower 입니다. 브로커 한 대가 죽어도 데이터와 서비스가 계속됩니다. 쪼개는 것은 파티션 수의 역할입니다.', NULL, NULL, NULL, NULL),
  (58, 7, '멱등 프로듀서의 역할 알기', '네트워크 오류로 프로듀서가 같은 메시지를 **재전송**해도 브로커에 **중복이 쌓이지 않게** 하려면 어떤 설정을 켜야 할까요?', '프로듀서 ID 와 순번(sequence)으로 중복을 걸러 냅니다.', NULL, NULL, '[]', 'choice', '["`auto.offset.reset=earliest`", "`retention.ms=0`", "`enable.idempotence=true` (멱등 프로듀서)", "`group.id` 를 비운다"]', 2, '멱등 프로듀서를 켜면 프로듀서가 시작할 때 Producer ID(PID)를 받고, 메시지마다 단조 증가하는 Sequence Number 를 붙입니다. 브로커는 파티션별 마지막 SeqNum 을 기억하다가 **이미 받은 번호면 중복으로 버립니다.** 켜면 `acks=all` 등이 자동으로 설정됩니다.', NULL, NULL, NULL, NULL),
  (58, 8, 'DLQ 가 필요한 이유 알기', '어떤 메시지는 **파싱할 수 없는 형식**이라 몇 번을 재시도해도 계속 실패하고, 이 때문에 뒤의 정상 메시지까지 처리가 막혔습니다. 이럴 때 쓰는 방법은 무엇일까요?', '실패한 메시지를 버리지 않으면서도 나머지 처리를 막지 않게 따로 빼 둡니다.', NULL, NULL, '[]', 'choice', '["실패한 메시지를 무한히 재시도한다", "컨슈머를 모두 재시작한다", "토픽을 삭제하고 다시 만든다", "재시도 한도를 넘긴 메시지를 **DLQ(Dead Letter Queue)** 로 옮겨 격리하고, 나중에 원인을 분석·재처리한다"]', 3, '재시도해도 계속 실패하는 **poison message** 를 재시도 루프에 그대로 두면 정상 메시지까지 막힙니다. 한도(예: 3회)를 넘긴 메시지를 **DLQ** 로 옮기면 문제 메시지는 격리하고 나머지는 계속 처리하며, 실패한 메시지는 버려지지 않고 보관됩니다.', NULL, NULL, NULL, NULL),
  (58, 9, 'CDC 가 무엇인지 알기', '**CDC(Change Data Capture)** 는 무엇일까요?', 'DB 를 주기적으로 통째로 조회하는 것과 비교해 보세요.', NULL, NULL, '[]', 'choice', '["데이터베이스에서 **바뀐 내용(INSERT·UPDATE·DELETE)만 변경 로그에서 읽어** 다른 시스템으로 전달하는 방식이다", "DB 전체를 매 분마다 SELECT 해서 복사하는 방식이다", "테이블 구조를 변경하는 DDL 도구이다", "DB 백업 파일을 압축하는 도구이다"]', 0, 'CDC 는 DB 의 **변경 로그**(MariaDB/MySQL 은 binlog, PostgreSQL 은 WAL)를 읽어 바뀐 행만 이벤트로 흘려보냅니다. 매번 전체를 조회하는 방식보다 DB 부하가 적고 지연이 짧으며 삭제도 감지합니다.', NULL, NULL, NULL, NULL),
  (58, 10, 'binlog 가 기록하는 것 알기', 'MariaDB/MySQL 의 **binlog(Binary Log)** 에 기록되는 것으로 알맞은 것은 무엇일까요?', '데이터를 바꾸는 이벤트만 순서대로 기록합니다.', NULL, NULL, '[]', 'choice', '["모든 SELECT 쿼리와 접속 기록", "INSERT, UPDATE, DELETE 와 DDL 같은 **데이터를 바꾸는 이벤트** (SELECT 는 기록하지 않는다)", "서버의 CPU·메모리 사용량", "애플리케이션 에러 로그"]', 1, 'binlog 는 데이터를 바꾸는 이벤트(INSERT·UPDATE·DELETE, DDL, 트랜잭션 커밋)를 **순서대로** 기록한 바이너리 로그입니다. 복제(replication)와 시점 복구(PITR), 그리고 Debezium 같은 CDC 도구가 이 로그를 읽습니다. (PostgreSQL 의 WAL, Oracle 의 Redo Log 와 유사한 개념)', NULL, NULL, NULL, NULL),
  (58, 11, 'Debezium 으로 변경이 흘러가는 순서 놓기', 'MariaDB 에서 행이 하나 바뀌었을 때, CDC 로 Kafka 까지 전달되는 흐름을 **앞에서 뒤 순서**대로 놓으세요.', 'DB 가 기록한 변경 로그를 읽는 도구가 이벤트로 바꿔 Kafka 로 보냅니다.', NULL, NULL, '[]', 'order', '["Debezium 이 binlog 를 읽어 변경 이벤트로 바꾼다", "변경 이벤트가 Kafka 토픽에 쌓인다", "애플리케이션이 행을 UPDATE 하고 커밋한다", "컨슈머(예: 검색 색인, 데이터 웨어하우스)가 토픽을 읽어 처리한다"]', NULL, '**UPDATE·커밋 → binlog 기록 → Debezium 이 binlog 를 읽어 변경 이벤트로 변환 → Kafka 토픽에 적재 → 컨슈머가 읽어 처리** 순서입니다. 앱이 이벤트를 직접 발행하지 않아도 DB 변경이 자동으로 이벤트가 됩니다.', '[2, 0, 1, 3]', NULL, NULL, NULL),
  (58, 12, 'Debezium 에 필요한 MySQL 권한 이해하기', 'Debezium 계정에 `SELECT`, `LOCK TABLES`, `RELOAD`, `SHOW DATABASES`, `REPLICATION SLAVE`, `REPLICATION CLIENT` 를 부여합니다. 이 중 **`SELECT` 가 필요한 이유**로 알맞은 것은 무엇일까요?', 'Debezium 이 처음 연결할 때는 binlog 이전의 기존 데이터를 어떻게 가져올까요?', NULL, NULL, '[]', 'choice', '["binlog 파일을 직접 읽기 위해서이다", "테이블을 잠그기 위해서이다", "처음 연결할 때 대상 테이블 전체를 읽어 Kafka 로 보내는 **초기 스냅샷**을 위해서이다 (이후 변경은 binlog 로 읽는다)", "데이터베이스 목록을 보기 위해서이다"]', 2, '`SELECT` 는 **초기 스냅샷**(기존 데이터 전체 읽기)에 필요하고, `LOCK TABLES` 는 스냅샷 중 일관된 읽기를 위해 잠그는 데, `REPLICATION SLAVE`/`REPLICATION CLIENT` 는 binlog 를 **복제본처럼 읽고** 위치를 확인하는 데 씁니다. 스냅샷이 끝나면 이후 변경은 binlog 로만 따라갑니다.', NULL, NULL, NULL, NULL);
